const retriggerCandidates = `-- name: RetriggerCandidates :many
SELECT li.linear_id, li.identifier, li.linear_team, li.team, f.id AS finding_id, f.repo,
       last.id AS previous_id, (last.artifacts ? 'trigger-consumed')::bool AS trigger_consumed
FROM linear_issues li
JOIN findings f ON f.id = li.finding_id
JOIN LATERAL (
    SELECT e.id, e.finding_id, e.status, e.attempt, e.model, e.branch, e.pr_number, e.cost_usd, e.error, e.run_after, e.locked_at, e.created_at, e.updated_at, e.kind, e.repo, e.issue_identifier, e.linear_issue_id, e.rework_note, e.previous_id, e.worktree, e.job_dir, e.session_id, e.decision, e.decision_reason, e.rounds, e.gate, e.gate_reasons, e.pr_url, e.head_sha, e.pr_state, e.approved_by, e.approved_at, e.shepherd_cycles, e.shepherd_handled, e.num_turns, e.artifacts, e.started_at, e.finished_at, e.session_log, e.resume_note, e.wait_reason, e.worktree_removed_at, e.worktree_freed_bytes FROM executions e
    WHERE e.finding_id = f.id AND e.status <> 'canceled'
    ORDER BY e.id DESC LIMIT 1
) last ON true
WHERE li.role = 'primary' AND f.state = 'open'
  AND (last.status = 'failed' OR last.decision = 'blocked')
  AND last.pr_number IS NULL AND last.finished_at IS NOT NULL
ORDER BY li.id
`

