const triggerCandidates = `-- name: TriggerCandidates :many
SELECT li.linear_id, li.identifier, li.linear_team, li.team, li.url, f.id AS finding_id, f.repo
FROM linear_issues li JOIN findings f ON f.id = li.finding_id
WHERE li.role = 'primary' AND f.state = 'open'
  AND NOT EXISTS (SELECT 1 FROM executions e WHERE e.finding_id = f.id AND e.status <> 'canceled')
ORDER BY li.id
`

type TriggerCandidatesRow struct {
	LinearID   string `json:"linear_id"`
	Identifier string `json:"identifier"`
	LinearTeam string `json:"linear_team"`
	Team       string `json:"team"`
	Url        string `json:"url"`
	FindingID  int64  `json:"finding_id"`
	Repo       string `json:"repo"`
}

// Issues principais com achado aberto e sem execução não cancelada: o worker confere no Linear
// quais têm a label de gatilho (aplicada por um humano).
func (q *Queries) TriggerCandidates(ctx context.Context) ([]TriggerCandidatesRow, error) {
	rows, err := q.db.Query(ctx, triggerCandidates)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TriggerCandidatesRow{}
	for rows.Next() {
		var i TriggerCandidatesRow
		if err := rows.Scan(
			&i.LinearID,
			&i.Identifier,
			&i.LinearTeam,
			&i.Team,
			&i.Url,
			&i.FindingID,
			&i.Repo,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const triggerConsumedCounts = `-- name: TriggerConsumedCounts :one
SELECT count(*) FILTER (WHERE artifacts->'trigger-consumed'->>'summary' LIKE '%tirada pelo worker%')::bigint AS removed,
       count(*) FILTER (WHERE artifacts->'trigger-consumed'->>'summary' LIKE '%tirada pelo worker%'
                          AND updated_at > now() - interval '30 days')::bigint AS removed_30d,
       count(*)::bigint AS consumed
FROM executions WHERE artifacts ? 'trigger-consumed'
`

type TriggerConsumedCountsRow struct {
	Removed    int64 `json:"removed"`
	Removed30d int64 `json:"removed_30d"`
	Consumed   int64 `json:"consumed"`
}

// Gatilhos consumidos (ADR 0029): execuções que terminaram sem PR e em que o worker tirou a label
// de gatilho de uma pessoa (removed) ou registrou que ela já estava fora. Total e últimos 30 dias.
func (q *Queries) TriggerConsumedCounts(ctx context.Context) (TriggerConsumedCountsRow, error) {
	row := q.db.QueryRow(ctx, triggerConsumedCounts)
	var i TriggerConsumedCountsRow
	err := row.Scan(&i.Removed, &i.Removed30d, &i.Consumed)
	return i, err
}

const worktreeCleanupTotals = `-- name: WorktreeCleanupTotals :one
SELECT count(*)::int AS removed,
       COALESCE(sum(worktree_freed_bytes), 0)::bigint AS freed_bytes,
       COALESCE(sum(worktree_freed_bytes) FILTER (WHERE worktree_removed_at > now() - interval '7 days'), 0)::bigint AS freed_week
FROM executions WHERE worktree_freed_bytes IS NOT NULL
`

type WorktreeCleanupTotalsRow struct {
	Removed    int32 `json:"removed"`
	FreedBytes int64 `json:"freed_bytes"`
	FreedWeek  int64 `json:"freed_week"`
}

// sentinela status: worktrees removidos e disco liberado, no total e nos últimos 7 dias.
func (q *Queries) WorktreeCleanupTotals(ctx context.Context) (WorktreeCleanupTotalsRow, error) {
	row := q.db.QueryRow(ctx, worktreeCleanupTotals)
	var i WorktreeCleanupTotalsRow
	err := row.Scan(&i.Removed, &i.FreedBytes, &i.FreedWeek)
	return i, err
}

const worktreeSweepCandidates = `-- name: WorktreeSweepCandidates :many
SELECT id, finding_id, issue_identifier, worktree, status, pr_state, ended_at, worktree_removed_at, finding_active FROM (
    SELECT DISTINCT ON (e.worktree) e.id, e.finding_id, e.issue_identifier, e.worktree::text AS worktree,
           e.status, COALESCE(e.pr_state, '')::text AS pr_state,
           COALESCE(e.finished_at, e.updated_at)::timestamptz AS ended_at, e.worktree_removed_at,
           EXISTS (SELECT 1 FROM executions a WHERE a.finding_id = e.finding_id AND a.status IN ('queued', 'running'))::bool AS finding_active
    FROM executions e
    WHERE e.worktree IS NOT NULL AND e.worktree <> ''
    ORDER BY e.worktree, e.id DESC
) latest
WHERE latest.worktree_removed_at IS NULL
`

type WorktreeSweepCandidatesRow struct {
	ID                int64              `json:"id"`
	FindingID         int64              `json:"finding_id"`
	IssueIdentifier   string             `json:"issue_identifier"`
	Worktree          string             `json:"worktree"`
	Status            string             `json:"status"`
	PrState           string             `json:"pr_state"`
	EndedAt           pgtype.Timestamptz `json:"ended_at"`
	WorktreeRemovedAt pgtype.Timestamptz `json:"worktree_removed_at"`
	FindingActive     bool               `json:"finding_active"`
}

// Limpeza de worktrees (ADR 0037): a execução mais recente de cada caminho ainda não removido,
// com o fim dela e se o achado tem execução na fila ou rodando (que pode retomar no caminho).
func (q *Queries) WorktreeSweepCandidates(ctx context.Context) ([]WorktreeSweepCandidatesRow, error) {
	rows, err := q.db.Query(ctx, worktreeSweepCandidates)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WorktreeSweepCandidatesRow{}
	for rows.Next() {
		var i WorktreeSweepCandidatesRow
		if err := rows.Scan(
			&i.ID,
			&i.FindingID,
			&i.IssueIdentifier,
			&i.Worktree,
			&i.Status,
			&i.PrState,
			&i.EndedAt,
			&i.WorktreeRemovedAt,
			&i.FindingActive,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
